CREATE TABLE t1(a INTEGER, b INTEGER, c TEXT); CREATE TABLE t2(a INTEGER, b INTEGER, c TEXT); CREATE INDEX i2a ON t2(a); CREATE INDEX i2b ON t2(b); WITH RECURSIVE g(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM g WHERE i<50000) INSERT INTO t2(a,b,c) SELECT i,(i*3571+23)%500000,printf('number-%06d',(i*3571+23)%500000) FROM g;